const input = $input.first().json;
const body = input.body ?? input;
const required = ['order_number','customer_name','customer_phone','delivery_address'];
for (const key of required) {
  if (!body[key] || String(body[key]).trim() === '') throw new Error(`Missing required field: ${key}`);
}
const fields = ['order_number','created_at','updated_at','customer_name','customer_email','customer_phone','delivery_address','landmark','branch_city','branch_area','branch_address','delivery_type','scheduled_at','payment_method','payment_status','order_status','receipt_number','items_json','status_history_json'];
const order = {};
for (const key of fields) order[key] = String(body[key] ?? '');
for (const key of ['subtotal','discount','delivery_fee','total']) order[key] = Number(body[key] ?? 0);
let items = [];
try { items = JSON.parse(String(order.items_json || '[]')); } catch (error) { items = []; }
const itemRows = items.map(item => `<li>${String(item.name ?? '')} × ${Number(item.qty ?? 1)} — ₱${Number(item.line_total ?? 0).toFixed(2)}</li>`).join('');
const html = `<div style="font-family:Arial,sans-serif;line-height:1.5"><h2>Your FilipinOnly order was received</h2><p>Order <strong>${order.order_number}</strong> is now <strong>${order.order_status || 'Order received'}</strong>.</p><h3>Items</h3><ul>${itemRows || '<li>Items are shown on your receipt page.</li>'}</ul><p><strong>Total:</strong> ₱${order.total.toFixed(2)}</p><p><strong>Delivery:</strong> ${order.delivery_address}</p><p>Receipt: https://www.facebook.com/people/Filipinonly/61585837899219/</p></div>`;
return [{ json: { ok: true, message: 'Receipt notification prepared from MySQL order data.', order_number: order.order_number, order, email: { to: order.customer_email, subject: `FilipinOnly receipt ${order.order_number}`, html } } }];
